package com.greenocean.backend;
import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;
import jakarta.persistence.EntityManager;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import tools.jackson.databind.ObjectMapper;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"greenocean.security.admin-enabled=true","greenocean.live-support.enabled=true","greenocean.listener-support.duration-enabled=true","greenocean.listener-support.scheduling-enabled=true","greenocean.listener-support.queue-enabled=true"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseN2StaffingAccessTest {
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired EntityManager entities;@Autowired MockMvc mvc;@Autowired ObjectMapper json;PhaseIFixtures.Actor staff,listener;
 @BeforeEach void setup(){PhaseIFixtures.region(db);staff=PhaseIFixtures.member(db,users,tokens);listener=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,listener.id(),staff.id(),true);entities.clear();staff=PhaseIFixtures.session(db,users,tokens,staff.id());}
 String body(UUID who){return json.writeValueAsString(Map.of("listenerId",who,"startsAt",Instant.now().minusSeconds(30),"endsAt",Instant.now().plusSeconds(7200)));}
 void mfa(PhaseIFixtures.Actor who){db.update("UPDATE user_sessions SET mfa_authenticated_at=clock_timestamp() WHERE id=?",who.session());}
 @Test @Tag("malicious") void currentRoleWithoutRecentSecurityKeyCannotApproveWindow()throws Exception{mvc.perform(post("/api/v1/admin/listener-support/coverage").header("Authorization","Bearer "+staff.token()).contentType("application/json").content(body(listener.id()))).andExpect(status().isForbidden());assertThat(db.queryForObject("SELECT count(*) FROM listener_queue_coverage_windows WHERE listener_id=?",Integer.class,listener.id())).isZero();}
 @Test @Tag("happy") void currentIndependentStaffAndRecentMfaCanApproveAndRevoke()throws Exception{mfa(staff);var result=mvc.perform(post("/api/v1/admin/listener-support/coverage").header("Authorization","Bearer "+staff.token()).contentType("application/json").content(body(listener.id()))).andExpect(status().isCreated()).andReturn();UUID id=UUID.fromString(json.readTree(result.getResponse().getContentAsString()).get("id").asText());mvc.perform(post("/api/v1/admin/listener-support/coverage/"+id+"/revoke").header("Authorization","Bearer "+staff.token())).andExpect(status().isNoContent());assertThat(db.queryForObject("SELECT revoked_at IS NOT NULL FROM listener_queue_coverage_windows WHERE id=?",Boolean.class,id)).isTrue();}
 @Test @Tag("malicious") void staleMfaAndDemotedRoleCannotUseOldPrivileges()throws Exception{db.update("UPDATE user_sessions SET mfa_authenticated_at=clock_timestamp()-INTERVAL '1 hour' WHERE id=?",staff.session());mvc.perform(get("/api/v1/admin/listener-support/coverage").header("Authorization","Bearer "+staff.token())).andExpect(status().isForbidden());mfa(staff);db.update("DELETE FROM user_roles WHERE user_id=? AND role_id IN(SELECT id FROM roles WHERE name='MODERATOR')",staff.id());mvc.perform(get("/api/v1/admin/listener-support/coverage").header("Authorization","Bearer "+staff.token())).andExpect(status().isUnauthorized());}
 @Test @Tag("malicious") void listenerCannotApproveOwnStaffingEvenWithStaffRoleAndMfa()throws Exception{db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name='MODERATOR' ON CONFLICT DO NOTHING",listener.id());entities.clear();var actor=PhaseIFixtures.session(db,users,tokens,listener.id());mfa(actor);mvc.perform(post("/api/v1/admin/listener-support/coverage").header("Authorization","Bearer "+actor.token()).contentType("application/json").content(body(actor.id()))).andExpect(status().isForbidden());}
}
